sparql:
SELECT (COUNT(?p) AS ?artists) WHERE {
  SELECT ?p WHERE {
    ?w a mc:Work ; mc:artist ?p ; mc:museum ?m .
  }
  GROUP BY ?p
  HAVING (COUNT(DISTINCT ?m) > 1)
}

SELECT DISTINCT ?w ?title WHERE {
  ?w mc:museum "rijksmuseum" ; dcterms:title ?title .
  { ?w mc:subject ?c } UNION { ?w mc:aiSubject ?c }
  ?c skos:prefLabel|skos:altLabel ?l .
  FILTER(CONTAINS(LCASE(STR(?l)), "landscape"))
}

SELECT DISTINCT ?w ?title WHERE {
  ?w a mc:Work ; dcterms:title ?title .
  { ?w mc:style ?s } UNION { ?w mc:inferredStyle ?s }
  ?s skos:prefLabel ?sl . FILTER(LCASE(STR(?sl)) = "impressionism")
  { ?w mc:subject ?c } UNION { ?w mc:aiSubject ?c }
  ?c skos:prefLabel|skos:altLabel ?l . FILTER(LCASE(STR(?l)) = "snow")
}

SELECT (COUNT(DISTINCT ?w) AS ?n) WHERE {
  ?w a mc:Work ; mc:aiSubject ?c .
  FILTER NOT EXISTS { ?w mc:subject ?c }
}

SELECT DISTINCT ?w ?title WHERE {
  ?w mc:aiSubject ?c ; dcterms:title ?title .
  ?c skos:prefLabel|skos:altLabel ?l . FILTER(LCASE(STR(?l)) = "night")
  FILTER NOT EXISTS {
    ?w mc:subject ?mc .
    ?mc skos:prefLabel|skos:altLabel ?ml . FILTER(LCASE(STR(?ml)) = "night")
  }
}

SELECT DISTINCT ?p ?artist WHERE {
  ?p mc:movement ?m ; rdfs:label ?artist .
  ?m skos:prefLabel|skos:altLabel ?ml . FILTER(LCASE(STR(?ml)) = "hague school")
} ORDER BY ?artist

SELECT DISTINCT ?w ?title ?year WHERE {
  ?w a mc:Work ; dcterms:title ?title ; mc:beginYear ?year .
  FILTER(?year < 1870)
  { ?w mc:subject ?c } UNION { ?w mc:aiSubject ?c }
  ?c skos:prefLabel|skos:altLabel ?l .
  FILTER(CONTAINS(LCASE(STR(?l)), "boat"))
} ORDER BY ?year

SELECT DISTINCT ?w ?title ?attribution WHERE {
  ?w mc:qualifiedArtist ?p ; dcterms:title ?title .
  ?p rdfs:label ?attribution .
  FILTER(CONTAINS(LCASE(STR(?attribution)), "van gogh"))
}

SELECT DISTINCT ?w ?title WHERE {
  ?w mc:museum "met" ; dcterms:title ?title .
  { ?w mc:subject ?c1 } UNION { ?w mc:aiSubject ?c1 }
  ?c1 skos:prefLabel|skos:altLabel ?l1 .
  FILTER(CONTAINS(LCASE(STR(?l1)), "portrait"))
  { ?w mc:subject ?c2 } UNION { ?w mc:aiSubject ?c2 }
  ?c2 skos:prefLabel|skos:altLabel ?l2 .
  FILTER(CONTAINS(LCASE(STR(?l2)), "woman") || CONTAINS(LCASE(STR(?l2)), "women") || CONTAINS(LCASE(STR(?l2)), "female"))
}
